solution.code:
// Tres reglas para los eventos de pagos de la tienda.
export const reglas = {
  revision: {
    source: ["tienda.pagos"],
    "detail-type": ["Pago procesado"],
    detail: { importe: [{ numeric: [">", 1000] }] },
  },
  rechazos: {
    source: ["tienda.pagos"],
    "detail-type": ["Pago rechazado"],
    detail: { entorno: [{ "anything-but": "pruebas" }] },
  },
  clientesVip: {
    source: ["tienda.pagos"],
    detail: { cliente: [{ prefix: "vip-" }] },
  },
};

spec.code:
assert.deepStrictEqual(Object.keys(reglas).sort(), ["clientesVip", "rechazos", "revision"]);
for (const [nombre, patron] of Object.entries(reglas)) {
  assert.deepStrictEqual(aws.events.validatePattern(patron), [], "La regla " + nombre + " no es un patrón válido");
}

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
const evento = pago("Pago procesado", { importe: 2500, entorno: "produccion", cliente: "ana" });
assert.strictEqual(aws.events.matches(reglas.revision, evento), true, "La revisión no recibe un pago procesado de 2500");

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
const evento = pago("Pago procesado", { importe: 40, entorno: "produccion", cliente: "vip-ana" });
assert.strictEqual(aws.events.matches(reglas.clientesVip, evento), true, "La regla VIP no recibe el pago de vip-ana");

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
for (const importe of [800, 1000]) {
  const evento = pago("Pago procesado", { importe, entorno: "produccion", cliente: "ana" });
  assert.strictEqual(aws.events.matches(reglas.revision, evento), false, "Un pago de " + importe + " no supera 1000");
}

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
const evento = pago("Pago rechazado", { importe: 5000, entorno: "produccion", cliente: "ana" });
assert.strictEqual(aws.events.matches(reglas.revision, evento), false, "La revisión solo es para pagos procesados");

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
for (const entorno of ["produccion", "staging"]) {
  const evento = pago("Pago rechazado", { importe: 50, entorno, cliente: "ana" });
  assert.strictEqual(aws.events.matches(reglas.rechazos, evento), true, "Un rechazo del entorno " + entorno + " debe llegar a la regla");
}

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
const evento = pago("Pago rechazado", { importe: 50, entorno: "pruebas", cliente: "ana" });
assert.strictEqual(aws.events.matches(reglas.rechazos, evento), false, "Los rechazos del entorno de pruebas no deben llegar");

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
const evento = pago("Pago procesado", { importe: 50, entorno: "produccion", cliente: "ana" });
assert.strictEqual(aws.events.matches(reglas.rechazos, evento), false, "Un pago procesado no es un rechazo");

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
const evento = pago("Pago procesado", { importe: 40, entorno: "produccion", cliente: "ana-vip" });
assert.strictEqual(aws.events.matches(reglas.clientesVip, evento), false, "Un cliente que no empieza por vip- no es VIP");

const pago = (tipo: string, detalle: Record<string, unknown>, origen: string = "tienda.pagos") => ({ source: origen, "detail-type": tipo, detail: detalle });
for (const tipo of ["Pago procesado", "Pago rechazado"]) {
  const evento = pago(tipo, { importe: 40, entorno: "produccion", cliente: "vip-luis" });
  assert.strictEqual(aws.events.matches(reglas.clientesVip, evento), true, tipo + " de un cliente VIP debe llegar a la regla");
}
const otro = pago("Pago procesado", { importe: 40, entorno: "produccion", cliente: "vip-luis" }, "tienda.devoluciones");
assert.strictEqual(aws.events.matches(reglas.clientesVip, otro), false, "Un evento de otro origen no debe llegar a la regla VIP");

