// Servicio que elige un asistente para ocho casos. Corrige la elección equivocada.
export const analitica = {
  casos: [
    { necesidad: "Dejar cada pedido en una cola hasta que un consumidor lo procese y lo borre", servicio: "sqs" },
    { necesidad: "Publicar un aviso una sola vez y entregarlo a varios suscriptores, incluidos correo y mensajes de texto", servicio: "sns" },
    { necesidad: "Reaccionar a eventos de aplicaciones propias, servicios de AWS y software de terceros, filtrándolos antes de entregarlos", servicio: "eventbridge" },
    { necesidad: "Procesar en tiempo real los registros de clics de una web que leen varias aplicaciones a la vez", servicio: "kinesis" },
    { necesidad: "Consultar con SQL estándar archivos que ya están en S3, sin montar servidores", servicio: "athena" },
    { necesidad: "Descubrir fuentes de datos, catalogarlas y prepararlas con trabajos ETL sin servidores", servicio: "glue" },
    { necesidad: "Crear una aplicación de IA generativa con modelos fundacionales de varias empresas", servicio: "bedrock" },
    { necesidad: "Construir, entrenar y desplegar un modelo propio de aprendizaje automático", servicio: "sagemaker" },
  ],
};

spec.code:
const fila = analitica.casos.find((f) => f.necesidad.startsWith("Consultar con SQL"));
assert.ok(fila, "debe existir la fila de las consultas con SQL");
assert.strictEqual(fila.servicio, "athena");

for (const fila of analitica.casos) {
  assert.ok(["sqs", "sns", "eventbridge", "kinesis", "athena", "glue", "bedrock", "sagemaker"].includes(fila.servicio), fila.necesidad + " tiene un servicio no válido");
}

const esperado: Record<string, string> = {
  "Dejar cada pedido en una cola hasta que un consumidor lo procese y lo borre": "sqs",
  "Publicar un aviso una sola vez y entregarlo a varios suscriptores, incluidos correo y mensajes de texto": "sns",
  "Reaccionar a eventos de aplicaciones propias, servicios de AWS y software de terceros, filtrándolos antes de entregarlos": "eventbridge",
  "Procesar en tiempo real los registros de clics de una web que leen varias aplicaciones a la vez": "kinesis",
  "Descubrir fuentes de datos, catalogarlas y prepararlas con trabajos ETL sin servidores": "glue",
  "Crear una aplicación de IA generativa con modelos fundacionales de varias empresas": "bedrock",
  "Construir, entrenar y desplegar un modelo propio de aprendizaje automático": "sagemaker",
};
for (const [necesidad, servicio] of Object.entries(esperado)) {
  const fila = analitica.casos.find((f) => f.necesidad === necesidad);
  assert.ok(fila, necesidad + " debe seguir existiendo");
  assert.strictEqual(fila.servicio, servicio);
}
